mapper.select:
SELECT sb.student_id as "studentId", cce.coach_id as "coachId", cce.course_id as "courseId", sb.user_course_package_id as "userCoursePackageId", cce.id as "sessionEventId", cce.title as "title", cce.start_ts::timestamp as "startTs", cce.end_ts::timestamp as "endTs", cce.capacity as "capacity", cce.booked_count as "bookedCount", sb.status as "bookingStatus", sb.booked_at::timestamp as "bookedAt", sb.cancelled_at::timestamp as "cancelledAt" FROM public.session_booking sb JOIN public.coach_calendar_event cce ON cce.id = sb.event_id WHERE cce.kind = 'session' AND sb.student_id = #{studentId}
AND cce.start_ts >= #{fromDate}
AND cce.start_ts < #{toDate}
ORDER BY cce.start_ts ASC
